import{z as B,x as A,o as t,c as m,q as n,j as s,D as r,d as l,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Watermark 与乱序","description":"","frontmatter":{"title":"Watermark 与乱序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/watermark-late-events.md","filePath":"cs/watermark-late-events.md","lastUpdated":1791063341000}'),d={name:"cs/watermark-late-events.md"};function p(k,a,w,u,D,c){const E=A("Mermaid");return t(),m("div",null,[a[2]||(a[2]=n('<h1 id="watermark-与乱序" tabindex="-1">Watermark 与乱序 <a class="header-anchor" href="#watermark-与乱序" aria-label="Permalink to &quot;Watermark 与乱序&quot;">​</a></h1><div class="epigraph"><p>事件时间窗口要关，必须有一条「不会再有更早事件」的声明。watermark 是这条声明；它错了，结果就永久偏或状态永不释放。</p><footer>—— 据 Akidau et al., VLDB 2015；乱序流与迟到处理通识</footer></div><p><a href="/cs/stream-windows">上一课</a>切开窗口。缺口是<strong>乱序</strong>：网络与分区让事件时间 \\(t\\) 的记录在 \\(t+\\Delta\\) 才到。本课钉 watermark；恰好一次下一课谈投递语义，不在这里重讲窗口种类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>启发式 watermark（事件时间的分位数、或「处理时间减去 bound」）过快关窗会丢迟到；过慢则状态膨胀、延迟变大。允许迟到：关窗后的修订（retraction）或侧输出。缺口是把迟到当成一等错误，而不是「调大窗口」。</p><p><span class="marginnote">乱序不是 bug，是分区网络的常态。与分布式课的故障模型：迟到像漏发后的补包，不是崩溃。</span></p><p><span class="marginnote">直觉类比：watermark 像「进度条」——流水线宣布「10:01 之前的事件我确定收齐了」，窗口见进度条越过自己的末尾就放心关窗；进度条被最慢的那个分区拖住。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成：每源或每分区一条单调不减的 watermark，聚合取 min。触发器：on-time 一次，allowed lateness 内再更新。监控：迟到率、关窗延迟、状态字节。与表格式：修订写成 changelog。</p>',9)),(t(),s(o,null,{default:r(()=>[i(E,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20W%5B%22watermark%22%5D%0A%20%20W%20--%3E%20CLOSE%5B%22%E5%85%B3%E7%AA%97%22%5D%0A%20%20LATE%5B%22%E8%BF%9F%E5%88%B0%22%5D%20--%3E%20REV%5B%22%E4%BF%AE%E8%AE%A2%20%2F%20%E4%BE%A7%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"数字实例：分区 A 的进度到 10:05、分区 B 只到 10:01，全局 watermark 取 min \\(= 10{:}01\\)；B 只要停一分钟，所有 10:01 之后的窗口都得干等——这正是「空闲源要发空闲 watermark」的原因。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"watermark \\(w\\) 断言：事件时间 \\(\\lt w\\) 的记录不再进入主输出。这是安全性（不再改）与活性（窗能关）的折中。多源取 min，最慢分区拖住全局——像最小快照挡 GC。空闲源要空闲 watermark，否则窗永不关。检查点必须含 \\(w\\) 与窗口状态，否则恢复会重复关窗或永不关。",-1)),a[6]||(a[6]=e("p",null,"迟到策略：丢弃、侧输出、或撤回旧合计再发新值。后者要求下游能撤，接到恰好一次与幂等。乱序缓冲在关窗前按事件时间排一小段，像微型外部排序。启发式过快丢数据，过慢堆状态与延迟。",-1)),(t(),s(o,null,{default:r(()=>[i(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%88%86%E5%8C%BA%20A%3A%20%E8%BF%9B%E5%BA%A6%2010%3A05%22%5D%20--%3E%20MIN%5B%22%E5%85%A8%E5%B1%80%20watermark%20%3D%20min%20%3D%2010%3A01%22%5D%0A%20%20S2%5B%22%E5%88%86%E5%8C%BA%20B%3A%20%E8%BF%9B%E5%BA%A6%2010%3A01%22%5D%20--%3E%20MIN%0A%20%20MIN%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%E5%8F%AA%E5%85%B3%E5%88%B0%2010%3A01%22%5D%0A%20%20EV%5B%22%E6%96%B0%E5%88%B0%E4%BA%8B%E4%BB%B6%2C%20%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%2010%3A03%22%5D%20--%3E%20Q%7B%22%E6%97%A9%E4%BA%8E%E5%BD%93%E5%89%8D%20watermark%20%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%E5%90%A6%20--%3E%20ONTIME%5B%22%E6%8C%89%E6%97%B6%E8%BF%9B%E7%AA%97%2C%20%E6%AD%A3%E5%B8%B8%E5%90%88%E8%AE%A1%22%5D%0A%20%20Q%20--%20%E6%98%AF%20--%3E%20OUT%5B%22%E6%92%A4%E5%9B%9E%E6%97%A7%E5%90%88%E8%AE%A1%2F%E4%BE%A7%E8%BE%93%E5%87%BA%2F%E4%B8%A2%E5%BC%83%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">常见误区：把 watermark 当成精确时钟。它是启发式声明，会错：设得太紧丢迟到数据，设得太松状态越积越大。正确姿势是配 allowed lateness 与修订合同，而不是指望启发式一次设对。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某启发式最优。下一课 exactly-once 假定窗已经能关。不要用处理时间 watermark 冒充事件时间正确。TrueTime 的 \\(\\epsilon\\) 是另一套时钟不确定度，不要混名。</p><p>后课默认：事件时间窗口必有 watermark 与迟到合同。watermark 是流的进度钟，不是墙钟。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>watermark 是关事件时间窗口的声明，会错。</li><li>迟到要有修订或侧输出合同；min 进度会被慢源拖住。</li><li>恰好一次下一课。</li><li>出处：Akidau et al., VLDB 2015。</li></ul>',6))])}const _=B(d,[["render",p]]);export{f as __pageData,_ as default};
